    # 3. Read Scheduled Deliveries
    sd = src['Scheduled Deliveries']
    sd_header_row = 1
    sd_headers = {norm_part_code(sd.cell(row=sd_header_row, column=col).value): col for col in range(1, sd.max_column + 1)}

    def sd_col(opt_names):
        for n in opt_names:
            if n in sd_headers and sd_headers[n] is not None:
                return sd_headers[n]
        return None

    sd_col_part = sd_col(['Part_Code', 'Part Code', 'Part'])
    sd_col_date = sd_col(['Delivery Date', 'Delivery_Date', 'Inbound Date', 'Date'])
    sd_col_units = sd_col(['Units', 'Inbound_Units', 'Quantity', 'Qty'])
    sd_col_crates = sd_col(['Crates', 'Crate_Count'])

    if sd_col_part is None or sd_col_date is None:
        raise KeyError(f"Missing Part_Code and/or Delivery Date columns in Scheduled Deliveries: {sd_headers}")

    deliveries = {}  # part_code -> list of (delivery_date, units)
    for r in range(sd_header_row + 1, sd.max_row + 1):
        p = norm_part_code(sd.cell(row=r, column=sd_col_part).value)
        if not p:
            continue
        d = parse_date(sd.cell(row=r, column=sd_col_date).value)
        if d is None:
            continue

        units = None
        if sd_col_units is not None:
            units = sd.cell(row=r, column=sd_col_units).value
        # Units column takes precedence; fallback to crates * ratio later if needed
        crates = None
        if sd_col_crates is not None:
            crates = sd.cell(row=r, column=sd_col_crates).value

        deliveries.setdefault(p, []).append({'delivery_date': d, 'units': units, 'crates': crates})

    # 4. Read Ratio
    ratio_ws = src['Ratio']
    # As identified in Step 1:
    # header A1='Units_Per_Crate', value at A2
    units_per_crate = ratio_ws['A2'].value
    if units_per_crate is None:
        raise ValueError('Units_Per_Crate missing at Ratio!A2')
    ratio = float(units_per_crate)
    if ratio <= 0:
        raise ValueError(f'Invalid Units_Per_Crate ratio: {ratio!r}')

    # 5. Compute metadata
    remaining_days = (planning_end - as_of_date).days

    # 6. Compute metrics
    results = []
    for p in parts:
        part_code = p['Part_Code']
        current_units = p['Current_Units']
        daily = p['Daily_Consumption_Units']

        # Normalize numeric values
        current_units_num = None if current_units is None else float(current_units)
        daily_num = None if daily is None else float(daily)

        if daily_num is not None and daily_num > 0 and current_units_num is not None:
            current_doh = current_units_num / daily_num
            projected_stockout = as_of_date + datetime.timedelta(days=int(math.floor(current_doh)))
        else:
            current_doh = None
            projected_stockout = None

        part_delivs = deliveries.get(part_code, [])
        earliest_delivery = min((x['delivery_date'] for x in part_delivs), default=None)

        inbound_units_by_end = 0.0
        for x in part_delivs:
            if x['delivery_date'] <= planning_end:
                u = x.get('units')
                if u is None and x.get('crates') is not None:
                    u = float(x['crates']) * ratio
                if u is None:
                    continue
                inbound_units_by_end += float(u)

        if daily_num is not None and daily_num > 0 and current_units_num is not None:
            delivered_doh_to_end = (current_units_num + inbound_units_by_end) / daily_num
            remaining_demand_units = daily_num * remaining_days
        else:
            delivered_doh_to_end = None
            remaining_demand_units = (daily_num * remaining_days) if (daily_num is not None) else None

        if remaining_demand_units is None or current_units_num is None:
            additional_units_needed = None
        else:
            additional_units_needed = max(0.0, remaining_demand_units - current_units_num - inbound_units_by_end)

        if additional_units_needed is None or additional_units_needed <= 0:
            crates_required = 0
            rounding_applied = False
        else:
            raw = additional_units_needed / ratio
            crates_required = int(math.ceil(raw))
            rounding_applied = (raw != crates_required)

        # Required delivery date logic
        if crates_required == 0:
            required_delivery = None
        else:
            if projected_stockout is None:
                required_delivery = None
            else:
                if earliest_delivery is not None and earliest_delivery <= projected_stockout:
                    if delivered_doh_to_end is None:
                        required_delivery = projected_stockout
                    else:
                        required_delivery = as_of_date + datetime.timedelta(days=int(math.floor(delivered_doh_to_end)))
                else:
                    required_delivery = projected_stockout

        if crates_required > 0:
            earlier_required = (earliest_delivery is None) or (required_delivery is not None and required_delivery < earliest_delivery)
        else:
            earlier_required = False

        results.append({
            'Part_Code': part_code,
            'Current_Units': int(current_units) if isinstance(current_units, int) else current_units_num,
            'Daily_Consumption_Units': int(daily) if isinstance(daily, int) else daily_num,
            'Current_DOH': current_doh,
            'Projected_Stockout_Date': projected_stockout,
            'Inbound_Units_By_Sep30': inbound_units_by_end,
            'Delivered_DOH_To_Sep30': delivered_doh_to_end,
            'Remaining_September_Demand_Units': remaining_demand_units,
            'Additional_Units_Needed': additional_units_needed,
            'Crates_Required_Rounded_Up': crates_required,
            'Earliest_Scheduled_Delivery_Date': earliest_delivery,
            'Required_Delivery_Date': required_delivery,
            'Rounding_Applied': bool(rounding_applied),
            'Earlier_Delivery_Required': bool(earlier_required),
        })

    # 7. Write output workbook
    out = Workbook()
    # Remove default sheet
    default_ws = out.active
    out.remove(default_ws)

    ws1 = out.create_sheet('Part_Results')

    # Metadata A1:B4
    ws1['A1'].value = 'AsOfDate'
    ws1['B1'].value = as_of_date.isoformat()
    ws1['A2'].value = 'PlanningHorizonEnd'
    ws1['B2'].value = planning_end.isoformat()
    ws1['A3'].value = 'RemainingDaysInSeptember'
    ws1['B3'].value = remaining_days
    ws1['A4'].value = 'Units_Per_Crate'
    ws1['B4'].value = ratio

    header = [
        'Part_Code',
        'Current_Units',
        'Daily_Consumption_Units',
        'Current_DOH',
        'Projected_Stockout_Date',
        'Inbound_Units_By_Sep30',
        'Delivered_DOH_To_Sep30',
        'Remaining_September_Demand_Units',
        'Additional_Units_Needed',
        'Crates_Required_Rounded_Up',
        'Earliest_Scheduled_Delivery_Date',
        'Required_Delivery_Date',
        'Rounding_Applied',
        'Earlier_Delivery_Required',
    ]

    for c, name in enumerate(header, start=1):
        ws1.cell(row=6, column=c).value = name

    date_cols = {'Projected_Stockout_Date', 'Required_Delivery_Date', 'Earliest_Scheduled_Delivery_Date'}

    for i, row in enumerate(results, start=7):
        for c, key in enumerate(header, start=1):
            v = row.get(key)
            if v is None:
                continue
            if key in date_cols:
                ws1.cell(row=i, column=c).value = date_to_iso(v)
            else:
                ws1.cell(row=i, column=c).value = v

    # 8. Sheet 2: Additional_Resupply_Needed
    ws2 = out.create_sheet('Additional_Resupply_Needed')
    add_header = [
        'Part_Code',
        'Required_Delivery_Date',
        'Crates_Required_Rounded_Up',
        'Additional_Units_Needed',
        'Rounding_Applied',
        'Earlier_Delivery_Required',
    ]
    for c, name in enumerate(add_header, start=1):
        ws2.cell(row=1, column=c).value = name

    out_row = 2
    for row in results:
        if row['Crates_Required_Rounded_Up'] and row['Crates_Required_Rounded_Up'] > 0:
            for c, key in enumerate(add_header, start=1):
                v = row.get(key)
                if v is None:
                    continue
                if key == 'Required_Delivery_Date':
                    ws2.cell(row=out_row, column=c).value = date_to_iso(v)
                else:
                    ws2.cell(row=out_row, column=c).value = v
            out_row += 1

    out.save(OUT_PATH)
    print('Saved successfully.')


if __name__ == '__main__':
    main()
